import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname } from 'node:path'

async function read(path) { return readFile(path, 'utf8') }
async function write(path, content) { await mkdir(dirname(path), { recursive: true }); await writeFile(path, content, 'utf8') }
async function replace(path, from, to) {
  const source = await read(path)
  if (!source.includes(from)) throw new Error(`Missing replacement anchor in ${path}: ${from.slice(0, 80)}`)
  await write(path, source.replace(from, to))
}
async function replaceAll(path, from, to) {
  const source = await read(path)
  if (!source.includes(from)) throw new Error(`Missing replacement anchor in ${path}: ${from}`)
  await write(path, source.split(from).join(to))
}

