// World root service: every world gets its own managed local filesystem.
await write('packages/server/src/services/world-root-service.ts', `import { mkdir, realpath } from 'node:fs/promises'\nimport { join, resolve, sep } from 'node:path'\n\nexport interface WorldRoot {\n  worldId: string\n  rootPath: string\n  filesPath: string\n  assetsPath: string\n  exportsPath: string\n  cachePath: string\n}\n\nexport class WorldRootService {\n  readonly #root: string\n\n  constructor(stateRoot: string) {\n    this.#root = resolve(stateRoot, 'worlds')\n  }\n\n  async ensure(worldId: string): Promise<WorldRoot> {\n    const safeId = encodeURIComponent(worldId)\n    const rootPath = resolve(this.#root, safeId)\n    if (rootPath !== this.#root && !rootPath.startsWith(\`${'${this.#root}'}\${sep}\`)) throw new Error('World root escaped managed data directory')\n    const filesPath = join(rootPath, 'files')\n    const assetsPath = join(rootPath, 'assets')\n    const exportsPath = join(rootPath, 'exports')\n    const cachePath = join(rootPath, 'cache')\n    await Promise.all([filesPath, assetsPath, exportsPath, cachePath].map((path) => mkdir(path, { recursive: true })))\n    return { worldId, rootPath: await realpath(rootPath), filesPath: await realpath(filesPath), assetsPath: await realpath(assetsPath), exportsPath: await realpath(exportsPath), cachePath: await realpath(cachePath) }\n  }\n}\n`)

await write('packages/server/src/services/world-file-service.ts', `import type { WorkspaceFileList, WorkspaceFilePreview } from './workspace-file-service.js'\nimport { WorkspaceFileService } from './workspace-file-service.js'\nimport type { WorldRootService } from './world-root-service.js'\n\nexport class WorldFileService {\n  readonly #roots: WorldRootService\n  readonly #services = new Map<string, Promise<WorkspaceFileService>>()\n\n  constructor(roots: WorldRootService) { this.#roots = roots }\n\n  async list(worldId: string, path: string): Promise<WorkspaceFileList> { return (await this.#service(worldId)).list(path) }\n  async preview(worldId: string, path: string): Promise<WorkspaceFilePreview> { return (await this.#service(worldId)).preview(path) }\n\n  #service(worldId: string): Promise<WorkspaceFileService> {\n    let service = this.#services.get(worldId)\n    if (service === undefined) {\n      service = this.#roots.ensure(worldId).then((root) => new WorkspaceFileService(root.filesPath))\n      this.#services.set(worldId, service)\n    }\n    return service\n  }\n}\n`)

await write('packages/server/src/services/world-settings-service.ts', `import { randomUUID } from 'node:crypto'\nimport { open, readFile, rename } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport type { EmployeeInstance, ReasoningEffort, WorldSettings } from '@dsh-cyber/contracts'\nimport type { WorldRootService } from './world-root-service.js'\n\nconst reasoning = new Set<ReasoningEffort>(['auto','off','minimal','low','medium','high','xhigh','max'])\n\nexport class WorldSettingsService {\n  readonly #roots: WorldRootService\n  constructor(roots: WorldRootService) { this.#roots = roots }\n\n  async get(worldId: string): Promise<WorldSettings> {\n    const root = await this.#roots.ensure(worldId)\n    try { return normalize(worldId, JSON.parse(await readFile(join(root.rootPath, 'settings.json'), 'utf8')) as Partial<WorldSettings>) }\n    catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; return defaults(worldId) }\n  }\n\n  async save(worldId: string, value: Partial<WorldSettings>): Promise<WorldSettings> {\n    const current = await this.get(worldId)\n    const next = normalize(worldId, { ...current, ...value, userIdentity: { ...current.userIdentity, ...value.userIdentity }, terminology: { ...current.terminology, ...value.terminology }, appearance: { ...current.appearance, ...value.appearance }, model: { ...current.model, ...value.model }, updatedAt: new Date().toISOString() })\n    const root = await this.#roots.ensure(worldId)\n    await atomic(join(root.rootPath, 'settings.json'), JSON.stringify(next, null, 2) + '\\n')\n    return next\n  }\n\n  async composeRuntimePrompt(worldId: string, character: EmployeeInstance, prompt: string): Promise<string> {\n    const settings = await this.get(worldId)\n    const worldContext = [\n      settings.lore ? \`世界观：\${settings.lore}\` : '',\n      settings.scenario ? \`当前场景：\${settings.scenario}\` : '',\n      \`用户在这个世界中的身份：\${settings.userIdentity.displayName}（\${settings.userIdentity.worldRole}），请称呼用户为“\${settings.userIdentity.addressAs}”。\`,\n      \`你在这个世界中是角色“\${character.displayName}”，身份为“\${character.role}”。保持自己的角色身份，不冒充其他角色。\`,\n      '当前世界与其他世界的数据、文件、记忆相互隔离。',\n    ].filter(Boolean).join('\\n')\n    return \`[当前世界设定]\\n\${worldContext}\\n\\n[用户请求]\\n\${prompt}\`\n  }\n}\n\nfunction defaults(worldId: string): WorldSettings {\n  return { schemaVersion: 1, worldId, lore: '', scenario: '', userIdentity: { displayName: '你', worldRole: '世界创建者', addressAs: '你' }, terminology: { characterSingular: '角色', characterPlural: '角色', addCharacterVerb: '添加角色', groupConversation: '群组会话', assignment: '任务' }, appearance: { accentColor: '#d7a52a', pageBackground: '#080d10', panelBackground: '#0d1419', ownerBubbleColor: '#263629', characterBubbleColor: '#141c22', textColor: '#edf2f4', mutedTextColor: '#84919a', panelRadius: 10, bubbleRadius: 8, buttonRadius: 7, fontScale: 1 }, model: { reasoningEffort: 'auto' }, updatedAt: new Date().toISOString() }\n}\nfunction normalize(worldId: string, value: Partial<WorldSettings>): WorldSettings {\n  const base = defaults(worldId)\n  const next = { ...base, ...value, schemaVersion: 1 as const, worldId, userIdentity: { ...base.userIdentity, ...(value.userIdentity ?? {}) }, terminology: { ...base.terminology, ...(value.terminology ?? {}) }, appearance: { ...base.appearance, ...(value.appearance ?? {}) }, model: { ...base.model, ...(value.model ?? {}) }, updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : new Date().toISOString() }\n  if (!reasoning.has(next.model.reasoningEffort)) next.model.reasoningEffort = 'auto'\n  for (const key of ['panelRadius','bubbleRadius','buttonRadius','fontScale'] as const) { if (!Number.isFinite(next.appearance[key])) next.appearance[key] = base.appearance[key] }\n  return next\n}\nasync function atomic(path: string, content: string): Promise<void> {\n  const temp = \`${'${path}'}.tmp-\${randomUUID()}\`\n  const handle = await open(temp, 'wx', 0o600)\n  try { await handle.writeFile(content, 'utf8'); await handle.sync() } finally { await handle.close() }\n  await rename(temp, path)\n}\n`)

await write('packages/server/src/services/world-access-service.ts', `import { createHash, randomBytes, randomUUID, scrypt as scryptCallback, timingSafeEqual } from 'node:crypto'\nimport { open, readFile, rename, rm } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { promisify } from 'node:util'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { WorldAccessSummary } from '@dsh-cyber/contracts'\nimport { HttpError } from '../http/errors.js'\nimport type { WorldRootService } from './world-root-service.js'\n\nconst scrypt = promisify(scryptCallback)\ninterface AccessFile { schemaVersion: 1; salt: string; hash: string; updatedAt: string }\ninterface Session { worldId: string; expiresAt: number }\n\nexport class WorldAccessService {\n  readonly #roots: WorldRootService\n  readonly #sessions = new Map<string, Session>()\n  readonly #failures = new Map<string, { count: number; blockedUntil: number }>()\n  constructor(roots: WorldRootService) { this.#roots = roots }\n\n  async summary(worldId: string, request?: IncomingMessage): Promise<WorldAccessSummary> {\n    const policy = await this.#read(worldId)\n    return { worldId, passwordEnabled: policy !== undefined, unlocked: policy === undefined || (request !== undefined && this.#token(request, worldId) !== undefined) }\n  }\n  async setPassword(worldId: string, password: string, response: ServerResponse): Promise<WorldAccessSummary> {\n    if (password.length < 4 || password.length > 128) throw new HttpError(422, 'invalid_world_password', '密码长度需为 4 到 128 个字符')\n    const salt = randomBytes(16)\n    const derived = await scrypt(password, salt, 32) as Buffer\n    const root = await this.#roots.ensure(worldId)\n    await atomic(join(root.rootPath, '.access.json'), JSON.stringify({ schemaVersion: 1, salt: salt.toString('base64url'), hash: derived.toString('base64url'), updatedAt: new Date().toISOString() }, null, 2) + '\\n')\n    this.#sessionsForWorld(worldId, true)\n    const token = this.#issue(worldId)\n    setCookie(response, worldId, token)\n    return { worldId, passwordEnabled: true, unlocked: true }\n  }\n  async clearPassword(worldId: string, response: ServerResponse): Promise<WorldAccessSummary> {\n    const root = await this.#roots.ensure(worldId)\n    await rm(join(root.rootPath, '.access.json'), { force: true })\n    this.#sessionsForWorld(worldId, true)\n    clearCookie(response, worldId)\n    return { worldId, passwordEnabled: false, unlocked: true }\n  }\n  async unlock(worldId: string, password: string, request: IncomingMessage, response: ServerResponse): Promise<WorldAccessSummary> {\n    const policy = await this.#read(worldId)\n    if (policy === undefined) return { worldId, passwordEnabled: false, unlocked: true }\n    const key = request.socket.remoteAddress ?? 'loopback'\n    const failure = this.#failures.get(key)\n    if (failure !== undefined && failure.blockedUntil > Date.now()) throw new HttpError(429, 'world_unlock_rate_limited', '尝试过于频繁，请稍后再试')\n    const derived = await scrypt(password, Buffer.from(policy.salt, 'base64url'), 32) as Buffer\n    const expected = Buffer.from(policy.hash, 'base64url')\n    if (derived.length !== expected.length || !timingSafeEqual(derived, expected)) {\n      const count = (failure?.count ?? 0) + 1\n      this.#failures.set(key, { count, blockedUntil: count >= 5 ? Date.now() + 30_000 : 0 })\n      throw new HttpError(401, 'world_password_invalid', '世界密码不正确')\n    }\n    this.#failures.delete(key)\n    const token = this.#issue(worldId)\n    setCookie(response, worldId, token)\n    return { worldId, passwordEnabled: true, unlocked: true }\n  }\n  lock(worldId: string, request: IncomingMessage, response: ServerResponse): void {\n    const token = this.#token(request, worldId)\n    if (token !== undefined) this.#sessions.delete(token)\n    clearCookie(response, worldId)\n  }\n  async assertUnlocked(worldId: string, request: IncomingMessage): Promise<void> {\n    if (await this.#read(worldId) === undefined) return\n    if (this.#token(request, worldId) === undefined) throw new HttpError(423, 'world_locked', '当前世界已锁定')\n  }\n  #issue(worldId: string): string { const token = randomBytes(32).toString('base64url'); this.#sessions.set(token, { worldId, expiresAt: Date.now() + 8 * 60 * 60 * 1000 }); return token }\n  #token(request: IncomingMessage, worldId: string): string | undefined {\n    const cookies = parseCookies(request.headers.cookie)\n    const token = cookies.get(cookieName(worldId))\n    if (token === undefined) return undefined\n    const session = this.#sessions.get(token)\n    if (session === undefined || session.worldId !== worldId || session.expiresAt <= Date.now()) { this.#sessions.delete(token); return undefined }\n    return token\n  }\n  #sessionsForWorld(worldId: string, remove: boolean): void { if (!remove) return; for (const [token, session] of this.#sessions) if (session.worldId === worldId) this.#sessions.delete(token) }\n  async #read(worldId: string): Promise<AccessFile | undefined> {\n    const root = await this.#roots.ensure(worldId)\n    try { const value = JSON.parse(await readFile(join(root.rootPath, '.access.json'), 'utf8')) as AccessFile; return value.schemaVersion === 1 && typeof value.salt === 'string' && typeof value.hash === 'string' ? value : undefined }\n    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined; throw error }\n  }\n}\nfunction cookieName(worldId: string): string { return 'dsh_world_' + createHash('sha256').update(worldId).digest('hex').slice(0, 16) }\nfunction parseCookies(value: string | undefined): Map<string, string> { const result = new Map<string,string>(); for (const part of value?.split(';') ?? []) { const index = part.indexOf('='); if (index > 0) result.set(part.slice(0,index).trim(), decodeURIComponent(part.slice(index+1).trim())) } return result }\nfunction setCookie(response: ServerResponse, worldId: string, token: string): void { response.setHeader('Set-Cookie', \`${'${cookieName(worldId)}'}=\${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Strict; Max-Age=28800\`) }\nfunction clearCookie(response: ServerResponse, worldId: string): void { response.setHeader('Set-Cookie', \`${'${cookieName(worldId)}'}=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0\`) }\nasync function atomic(path: string, content: string): Promise<void> { const temp = \`${'${path}'}.tmp-\${randomUUID()}\`; const handle = await open(temp, 'wx', 0o600); try { await handle.writeFile(content, 'utf8'); await handle.sync() } finally { await handle.close() }; await rename(temp, path) }\n`)

await write('packages/server/src/routes/world-settings-routes.ts', `import type { ModelProfile, WorldSettings } from '@dsh-cyber/contracts'\nimport type { SqliteStore } from '@dsh-cyber/persistence'\nimport type { Router } from '../http/router.js'\nimport { readJson, requiredString } from '../http/request.js'\nimport { writeJson } from '../http/response.js'\nimport type { WorldAccessService } from '../services/world-access-service.js'\nimport type { WorldSettingsService } from '../services/world-settings-service.js'\n\nexport function registerWorldSettingsRoutes(router: Router, dependencies: { store: SqliteStore; settings: WorldSettingsService; access: WorldAccessService }) {\n  const { store, settings, access } = dependencies\n  router.get(/^\\/api\\/worlds\\/([^/]+)\\/settings$/, async ({ request, response, params }) => { const worldId = params[0]!; if (store.getWorld(worldId) === undefined) throw new Error('World not found'); await access.assertUnlocked(worldId, request); writeJson(response, 200, { settings: await settings.get(worldId), access: await access.summary(worldId, request), models: store.listModelProfiles(store.getWorld(worldId)!.workspaceId) }) })\n  router.put(/^\\/api\\/worlds\\/([^/]+)\\/settings$/, async ({ request, response, params }) => { const worldId = params[0]!; await access.assertUnlocked(worldId, request); const body = await readJson(request); writeJson(response, 200, { settings: await settings.save(worldId, body as Partial<WorldSettings>) }) })\n  router.get(/^\\/api\\/worlds\\/([^/]+)\\/access$/, async ({ request, response, params }) => writeJson(response, 200, { access: await access.summary(params[0]!, request) }))\n  router.post(/^\\/api\\/worlds\\/([^/]+)\\/access\\/password$/, async ({ request, response, params }) => { const body = await readJson(request); writeJson(response, 200, { access: await access.setPassword(params[0]!, requiredString(body, 'password'), response) }) })\n  router.delete(/^\\/api\\/worlds\\/([^/]+)\\/access\\/password$/, async ({ response, params }) => writeJson(response, 200, { access: await access.clearPassword(params[0]!, response) }))\n  router.post(/^\\/api\\/worlds\\/([^/]+)\\/access\\/unlock$/, async ({ request, response, params }) => { const body = await readJson(request); writeJson(response, 200, { access: await access.unlock(params[0]!, requiredString(body, 'password'), request, response) }) })\n  router.post(/^\\/api\\/worlds\\/([^/]+)\\/access\\/lock$/, async ({ request, response, params }) => { access.lock(params[0]!, request, response); writeJson(response, 200, { ok: true }) })\n}\n`)

